import * as T from 'three';
// Ventilated visual enclosure for this educational rack, independent of charger.
export function coverBattery177(model){const part=model.userData.parts.get('battery');if(part.userData.cover177)return;const root=new T.Group();root.name='Resguardo ventilado banco baterías177';part.add(root);const paint=new T.MeshStandardMaterial({name:'Chapa pintada resguardo177',color:'#7c8989',metalness:.15,roughness:.62}),dark=new T.MeshStandardMaterial({color:'#172129',roughness:.8}),steel=new T.MeshStandardMaterial({color:'#a7b1b4',metalness:.8,roughness:.32});const box=(name,x,y,z,w,h,d,mat=paint,parent=root)=>{const o=new T.Mesh(new T.BoxGeometry(w,h,d),mat);o.name=name;o.position.set(x,y,z);parent.add(o);return o;};
box('Lateral izquierdo',4.37,.88,-1.7,.035,1.72,.94);box('Lateral derecho',6.85,.88,-1.7,.035,1.72,.94);box('Cubierta superior',5.61,1.75,-1.7,2.52,.035,.94);box('Trasera protegida',5.61,.88,-1.235,2.52,1.72,.035);
for(const side of[-1,1]){const door=new T.Group();door.name='Puerta resguardo baterías177';door.position.set(side<0?4.40:6.82,.07,-2.19);root.add(door);const cx=-side*.60;box('Panel principal',cx,.91,0,1.20,1.4,.035,paint,door);for(let i=0;i<7;i++){const l=box('Lama ventilación',cx,.10+i*.043,-.003,1.16,.030,.045,paint,door);l.rotation.x=.35;}box('Bastidor bajo',cx,.025,0,1.20,.045,.035,paint,door);box('Asidero',-side*1.13,.94,-.04,.022,.18,.025,steel,door);box('Etiqueta resguardo',cx,1.37,-.022,.24,.09,.006,dark,door);door.rotation.y=-side*1.75;door.userData.cover177=true;door.userData.opensToAisle196=true;model.userData.doors.push(door);}
part.userData.cover177=root;model.updateMatrixWorld(true);return root;}
